The functions `get_custom_cat_fn` and `get_custom_format_validator` are nearly identical. This code duplication makes maintenance harder, as any bug fix or improvement needs to be applied in two places.

This can be refactored into a single private helper function `_load_custom_function` that handles the common logic of loading a function from a path specified in the configuration.

```python
import os
import sys
import importlib.util
from typing import Callable, Any, Optional, Tuple
from omegaconf import OmegaConf, DictConfig

def _load_custom_function(
    config_path: str, module_name: str, config: DictConfig
) -> Optional[Tuple[Callable, DictConfig]]:
    """Loads a custom function from a file path specified in the config."""
    try:
        fn_config = OmegaConf.select(config, config_path)
        if not fn_config or not fn_config.path or not fn_config.name:
            print(f"No custom function path or name provided for {config_path}. Skipping.")
            return None

        file_path = fn_config.path
        function_name = fn_config.name
    except Exception as e:
        print(f"[ERROR] Could not access '{config_path}': {e}")
        print("Please ensure the configuration structure is correct.")
        return None

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Custom function file '{file_path}' not found.")

    try:
        spec = importlib.util.spec_from_file_location(module_name, file_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"Could not create module spec from '{file_path}'")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
    except Exception as e:
        raise RuntimeError(f"Error loading module from '{file_path}': {e}") from e

    if not hasattr(module, function_name):
        raise AttributeError(f"Function '{function_name}' not found in module '{file_path}'.")

    print(f"Using customized function '{function_name}' from '{file_path}'")
    return getattr(module, function_name), fn_config

def get_custom_cat_fn(config: DictConfig) -> Optional[Callable]:
    result = _load_custom_function(
        "actor_self_judgement.custom_cat_function", "custom_cat_module", config
    )
    if result is None:
        return None

    raw_fn, cat_fn_config = result
    cat_kwargs = dict(cat_fn_config.get("cat_kwargs", {}))

    def wrapped_fn(*args, **kwargs):
        final_kwargs = {**kwargs, **cat_kwargs}
        return raw_fn(*args, **final_kwargs)

    return wrapped_fn

def get_custom_format_validator(config: DictConfig) -> Optional[Callable]:
    result = _load_custom_function(
        "actor_self_judgement.custom_reward_format_validator", "custom_validator_module", config
    )
    if result is None:
        return None

    validator_fn, _ = result
    return validator_fn
```

